/**
 * Generated by vecDSL from script productCatalog version 1.0.
 * Product catalogue on Pinecone: schema, writes, vector, keyword and hybrid search
 *
 * Target: Pinecone (API 2026-07) through @pinecone-database/pinecone 9.2.0, Node.js >= 22.
 * API key: VECDSL_PINECONE_API_KEY. Other endpoints: VECDSL_PINECONE_URI (control plane),
 * VECDSL_PINECONE_INDEX_HOST (data plane, for example the API mock of docker-compose.yml).
 */

import * as rt from "./vecdslPineconeRuntime";

export interface ProductCatalogParameters {
  queryVector?: number[];
  maxPrice?: number;
  queryText?: string;
}

export async function connect(): Promise<rt.Client> {
  return rt.connect({
    uri: process.env.VECDSL_PINECONE_URI ?? "https://api.pinecone.io",
    api_key: rt.env("VECDSL_PINECONE_API_KEY"),
    index_host: process.env.VECDSL_PINECONE_INDEX_HOST,
  });
}

export class ProductCatalog {
  constructor(readonly client: rt.Client) {}

  static async open(client?: rt.Client): Promise<ProductCatalog> {
    return new ProductCatalog(client ?? (await connect()));
  }

  async close(): Promise<void> {
    await this.client.close();
  }

  async connectCloud() {
  }

  async dropOld() {
    if (await rt.hasCollection(this.client, { name: "products" })) {
      await rt.dropCollection(this.client, { name: "products" });
    }
  }

  async createProducts() {
    // Ignored on Pinecone: family on VectorIndex, maxDegree on VectorIndex, buildCandidates on VectorIndex.
    if (!await rt.hasCollection(this.client, { name: "products" })) {
      await rt.createCollection(this.client, {
        name: "products",
        fields: {
          embedding: { type: "dense_vector", dimension: 4, metric: "cosine" },
          title: { type: "string", full_text_search: { language: "en" } },
        },
        deployment: { cloud: "aws", region: "us-east-1" },
      });
    }
  }

  async seed() {
    return await rt.insertRows(this.client, {
      collection: {
        name: "products",
        namespace: "__default__",
        key: "id",
        key_type: "int",
        probe: { type: "dense_vector", field: "embedding", dim: 4 },
        limits: {
          title: { max_length: 256 },
          category: { max_length: 64 },
          tags: { max_items: 8 },
          embedding: { dim: 4 },
        },
      },
      rows: [
        {
          id: 1,
          title: "Milvus in action: vector database design",
          category: "books",
          price: 39.5,
          tags: ["vector", "database"],
          embedding: [0.9, 0.1, 0, 0.1],
        },
        {
          id: 2,
          title: "Approximate nearest neighbour search",
          category: "books",
          price: 52,
          tags: ["ann"],
          embedding: [0.8, 0.2, 0.1, 0],
        },
        {
          id: 3,
          title: "Espresso machine",
          category: "kitchen",
          price: 249,
          tags: ["coffee"],
          embedding: [0, 0.1, 0.9, 0.3],
        },
        {
          id: 4,
          title: "Graph databases explained",
          category: "books",
          price: 28,
          tags: ["graph", "database"],
          embedding: [0.5, 0.5, 0.2, 0.1],
        },
      ],
      wait: true,
    });
  }

  async similar(queryVector: number[], maxPrice: number) {
    return await rt.vectorSearch(this.client, {
      collection: { name: "products", namespace: "__default__", key: "id", key_type: "int" },
      field: "embedding",
      vector: queryVector,
      limit: 3,
      metric: "cosine",
      score_min: 0.2,
      filter: { $and: [{ category: { $eq: "books" } }, { price: { $lte: maxPrice } }] },
      output: ["title", "category", "price"],
    });
  }

  async keywords(queryText: string) {
    return await rt.keywordSearch(this.client, {
      collection: { name: "products", namespace: "__default__", key: "id", key_type: "int" },
      query: queryText,
      fields: ["title"],
      limit: 3,
      output: ["title", "price"],
    });
  }

  async hybrid(queryVector: number[], queryText: string) {
    return await rt.hybridSearch(this.client, {
      collection: { name: "products", namespace: "__default__", key: "id", key_type: "int" },
      legs: [
        { kind: "vector", field: "embedding", vector: queryVector, metric: "cosine" },
        { kind: "keyword", query: queryText, fields: ["title"] },
      ],
      limit: 3,
      fusion: "rrf",
      k: 60,
      output: ["title", "price"],
    });
  }

  async byId() {
    return await rt.getRows(this.client, {
      collection: { name: "products", namespace: "__default__", key: "id", key_type: "int" },
      ids: [1, 2],
      output: ["title", "price"],
    });
  }

  async cheapBooks() {
    return await rt.count(this.client, {
      collection: { name: "products", namespace: "__default__", key: "id", key_type: "int" },
      filter: { $and: [{ category: { $eq: "books" } }, { price: { $lt: 40 } }] },
    });
  }

  async reprice() {
    return await rt.updateRows(this.client, {
      collection: {
        name: "products",
        namespace: "__default__",
        key: "id",
        key_type: "int",
        probe: { type: "dense_vector", field: "embedding", dim: 4 },
        limits: {
          title: { max_length: 256 },
          category: { max_length: 64 },
          tags: { max_items: 8 },
          embedding: { dim: 4 },
        },
      },
      ids: [1],
      values: { price: 35 },
      wait: true,
    });
  }

  async similarToFirst() {
    const queryVector = await rt.recommendVector(this.client, {
      collection: { name: "products", namespace: "__default__", key: "id", key_type: "int" },
      field: "embedding",
      positives: [1],
      negatives: [3],
    });
    return await rt.vectorSearch(this.client, {
      collection: { name: "products", namespace: "__default__", key: "id", key_type: "int" },
      field: "embedding",
      vector: queryVector,
      limit: 2,
      metric: "cosine",
      output: ["title"],
      filter: { id: { $nin: [1, 3] } },
    });
  }

  async browse() {
    return await rt.scroll(this.client, {
      collection: { name: "products", namespace: "__default__", key: "id", key_type: "int" },
      limit: 10,
      filter: { tags: { $eq: "database" } },
      output: ["title", "tags"],
    });
  }

  async removeOne() {
    return await rt.deleteRows(this.client, {
      collection: {
        name: "products",
        namespace: "__default__",
        key: "id",
        key_type: "int",
        probe: { type: "dense_vector", field: "embedding", dim: 4 },
        limits: {
          title: { max_length: 256 },
          category: { max_length: 64 },
          tags: { max_items: 8 },
          embedding: { dim: 4 },
        },
      },
      ids: [4],
      wait: true,
    });
  }

  async remaining() {
    return await rt.count(this.client, { collection: { name: "products", namespace: "__default__", key: "id", key_type: "int" } });
  }
}

export async function run(parameters: ProductCatalogParameters = {}, client?: rt.Client) {
  const values: ProductCatalogParameters = { queryVector: [0.9, 0.1, 0, 0.1], maxPrice: 60, queryText: "vector database", ...parameters };
  const program = await ProductCatalog.open(client);
  try {
    return {
      connectCloud: await program.connectCloud(),
      dropOld: await program.dropOld(),
      createProducts: await program.createProducts(),
      seed: await program.seed(),
      similar: await program.similar(values.queryVector!, values.maxPrice!),
      keywords: await program.keywords(values.queryText!),
      hybrid: await program.hybrid(values.queryVector!, values.queryText!),
      byId: await program.byId(),
      cheapBooks: await program.cheapBooks(),
      reprice: await program.reprice(),
      similarToFirst: await program.similarToFirst(),
      browse: await program.browse(),
      removeOne: await program.removeOne(),
      remaining: await program.remaining(),
    };
  } finally {
    if (client === undefined) {
      await program.close();
    }
  }
}

function parse(argv: string[]): Record<string, unknown> {
  const names: string[] = ["queryVector", "maxPrice", "queryText"];
  const aliases: Record<string, string> = { "queryVector": "queryVector", "maxPrice": "maxPrice", "queryText": "queryText" };
  const parameters: Record<string, unknown> = {};
  for (const argument of argv) {
    const separator = argument.indexOf("=");
    if (separator < 0) {
      throw new TypeError(`expected name=value, got ${argument}`);
    }
    const given = argument.slice(0, separator);
    const name = aliases[given] ?? given;
    if (!names.includes(name)) {
      throw new TypeError(`unknown program parameter: ${given}`);
    }
    const raw = argument.slice(separator + 1);
    try {
      parameters[name] = JSON.parse(raw);
    } catch {
      parameters[name] = raw;
    }
  }
  return parameters;
}

if (require.main === module) {
  run(parse(process.argv.slice(2)))
    .then((result) => console.log(JSON.stringify(result, (_key, value: unknown) => (value === undefined ? null : value), 2)))
    .catch((error: unknown) => {
      console.error(error);
      process.exitCode = 1;
    });
}
